import { bsPrice, strikeForDelta, yearsToExpiry } from "./black-scholes.ts";
import { markLegs, summarizePayoff, type PayoffLeg } from "./payoff.ts";
import type { BucketId, QuoteBar } from "./types.ts";
import type { Regime } from "./regime.ts";
import { ivFallback } from "./universe.ts";

export type StrategyId =
  | "LONG_STOCK"
  | "LONG_CALL"
  | "LONG_PUT"
  | "CALL_DEBIT"
  | "PUT_DEBIT"
  | "BULL_PUT"
  | "BEAR_CALL"
  | "COVERED_CALL"
  | "COLLAR"
  | "CALENDAR_CALL"
  | "CALENDAR_PUT"
  | "DIAGONAL_CALL"
  | "IRON_CONDOR"
  | "LEAPS_CALL"
  | "PROTECTIVE";

export const ALL_STRATEGY_IDS: StrategyId[] = [
  "LONG_STOCK",
  "LONG_CALL",
  "LONG_PUT",
  "CALL_DEBIT",
  "PUT_DEBIT",
  "BULL_PUT",
  "BEAR_CALL",
  "COVERED_CALL",
  "COLLAR",
  "CALENDAR_CALL",
  "CALENDAR_PUT",
  "DIAGONAL_CALL",
  "IRON_CONDOR",
  "LEAPS_CALL",
  "PROTECTIVE",
];

export const DTE_CHOICES = [7, 14, 21, 45, 90, 180] as const;
export type DteChoice = (typeof DTE_CHOICES)[number];

export const STRATEGY_META: Record<
  StrategyId,
  { labelZh: string; labelEn: string; family: "beta" | "debit" | "credit" | "time" | "hedge" }
> = {
  LONG_STOCK: { labelZh: "正股", labelEn: "Long Stock", family: "beta" },
  LONG_CALL: { labelZh: "買入 Call", labelEn: "Long Call", family: "debit" },
  LONG_PUT: { labelZh: "買入 Put", labelEn: "Long Put", family: "hedge" },
  CALL_DEBIT: { labelZh: "Call 借記價差", labelEn: "Call Debit Spread", family: "debit" },
  PUT_DEBIT: { labelZh: "Put 借記價差", labelEn: "Put Debit Spread", family: "hedge" },
  BULL_PUT: { labelZh: "牛市 Put 貸記價差", labelEn: "Bull Put Spread", family: "credit" },
  BEAR_CALL: { labelZh: "熊市 Call 貸記價差", labelEn: "Bear Call Spread", family: "credit" },
  COVERED_CALL: { labelZh: "備兌 Call", labelEn: "Covered Call", family: "credit" },
  COLLAR: { labelZh: "領式", labelEn: "Collar", family: "hedge" },
  CALENDAR_CALL: { labelZh: "Call 日曆價差", labelEn: "Call Calendar", family: "time" },
  CALENDAR_PUT: { labelZh: "Put 日曆價差", labelEn: "Put Calendar", family: "time" },
  DIAGONAL_CALL: { labelZh: "Call 對角價差", labelEn: "Call Diagonal", family: "time" },
  IRON_CONDOR: { labelZh: "鐵鷹（有限風險）", labelEn: "Iron Condor", family: "credit" },
  LEAPS_CALL: { labelZh: "LEAPS Call", labelEn: "LEAPS Call", family: "debit" },
  PROTECTIVE: { labelZh: "保護性 Put", labelEn: "Protective Put", family: "hedge" },
};

export type StrategyPlan = {
  id: StrategyId;
  labelZh: string;
  labelEn: string;
  score: number;
  why: string[];
  avoid: boolean;
  symbol: string;
  spot: number;
  dte: number;
  farDte?: number;
  netDebit: number;
  maxProfit: number | null;
  maxLoss: number | null;
  breakevens: number[];
  riskReward: number | null;
  greeks: { delta: number; gamma: number; theta: number; vega: number };
  legs: PayoffLeg[];
  tickets: string[];
};

export type BuildOpts = { dte?: number; farDte?: number };

export function expiryFriday(daysAhead: number, from = Date.now()) {
  const d = new Date(from);
  d.setUTCDate(d.getUTCDate() + daysAhead);
  const delta = (5 - d.getUTCDay() + 7) % 7;
  d.setUTCDate(d.getUTCDate() + delta);
  return d.toISOString().slice(0, 10);
}

function px(spot: number, strike: number, expiry: string, iv: number, right: "CALL" | "PUT") {
  const t = Math.max(yearsToExpiry(expiry), 7 / 365);
  return bsPrice({ spot, strike, tYears: t, iv, right });
}

function greeksSum(legs: PayoffLeg[], spot: number) {
  const m = markLegs(legs, spot, { daysAhead: 0 });
  return { delta: m.delta, gamma: m.gamma, theta: m.theta, vega: m.vega };
}

export function formatLegTicket(l: PayoffLeg): string {
  const sign = l.side === "SHORT" ? "−" : "+";
  const qty = l.qty;
  const sym = l.symbol ?? "";
  if (l.kind === "CASH") return `${sign}${qty.toLocaleString("en-US")} USD CASH`;
  if (l.kind === "STOCK") return `${sign}${qty} ${sym} STOCK @ ${l.entry.toFixed(2)}`;
  const k = l.strike != null ? l.strike.toFixed(l.strike >= 100 ? 0 : 1) : "—";
  const exp = l.expiry ?? "";
  return `${sign}${qty} ${sym} ${l.kind} ${k}  ${exp}  @ ${l.entry.toFixed(2)}`;
}

export function formatTickets(legs: PayoffLeg[]): string[] {
  return legs.map(formatLegTicket);
}

function finish(
  partial: Omit<StrategyPlan, "netDebit" | "maxProfit" | "maxLoss" | "breakevens" | "riskReward" | "greeks" | "tickets">,
): StrategyPlan {
  const sum = summarizePayoff(partial.legs, partial.spot);
  const maxProfit = sum.maxProfit;
  const maxLoss = sum.maxLoss;
  const rr =
    maxProfit != null && maxLoss != null && maxLoss < 0 ? Math.abs(maxProfit / maxLoss) : null;
  return {
    ...partial,
    netDebit: sum.netDebit,
    maxProfit,
    maxLoss,
    breakevens: sum.breakevens,
    riskReward: rr,
    greeks: greeksSum(partial.legs, partial.spot),
    tickets: formatTickets(partial.legs),
  };
}

function stockLeg(symbol: string, spot: number, qty: number, bucket: BucketId): PayoffLeg {
  return {
    kind: "STOCK",
    side: "LONG",
    qty,
    entry: spot,
    multiplier: 1,
    symbol,
    bucket,
    note: "正股",
  };
}

function optLeg(
  symbol: string,
  right: "CALL" | "PUT",
  side: "LONG" | "SHORT",
  strike: number,
  expiry: string,
  iv: number,
  spot: number,
  bucket: BucketId,
  note: string,
  qty = 1,
): PayoffLeg {
  return {
    kind: right,
    side,
    qty,
    strike,
    expiry,
    iv,
    entry: px(spot, strike, expiry, iv, right),
    multiplier: 100,
    symbol,
    bucket,
    note,
  };
}

function overlayShares(spot: number) {
  if (spot >= 400) return 20;
  if (spot >= 150) return 50;
  return 100;
}

export function buildStrategy(id: StrategyId, quote: QuoteBar, iv: number, opts: BuildOpts = {}): StrategyPlan {
  const symbol = quote.symbol;
  const spot = quote.price;
  const vol = iv > 0 ? iv : ivFallback(symbol);
  const dte = opts.dte ?? (id === "LEAPS_CALL" ? 180 : id === "LONG_PUT" && (opts.farDte ?? 0) >= 80 ? 90 : 21);
  const farDte = opts.farDte ?? Math.max(dte + 70, 90);
  const near = expiryFriday(dte);
  const far = expiryFriday(farDte);
  const tNear = Math.max(yearsToExpiry(near), 7 / 365);
  const tFar = Math.max(yearsToExpiry(far), 30 / 365);
  const meta = STRATEGY_META[id];
  const kNear = (abs: number, right: "CALL" | "PUT") =>
    strikeForDelta({ spot, tYears: tNear, iv: vol, targetAbsDelta: abs, right });
  const kFar = (abs: number, right: "CALL" | "PUT") =>
    strikeForDelta({ spot, tYears: tFar, iv: vol, targetAbsDelta: abs, right });

  if (id === "LONG_STOCK") {
    const qty = symbol === "TQQQ" || symbol === "SQQQ" ? 8 : 10;
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte: 0,
      legs: [stockLeg(symbol, spot, qty, symbol === "TQQQ" ? "TACTICAL" : "CORE")],
    });
  }

  if (id === "LONG_CALL") {
    const strike = kNear(0.4, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [optLeg(symbol, "CALL", "LONG", strike, near, vol, spot, "TACTICAL", `${dte}DTE Δ40 Call`)],
    });
  }

  if (id === "LONG_PUT") {
    const target = dte >= 80 ? 0.12 : 0.25;
    const strike = kNear(target, "PUT");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(
          symbol,
          "PUT",
          "LONG",
          strike,
          near,
          vol,
          spot,
          "CONVEXITY",
          `${dte}DTE Δ${Math.round(target * 100)} Put`,
        ),
      ],
    });
  }

  if (id === "CALL_DEBIT") {
    const longK = kNear(0.4, "CALL");
    const shortK = kNear(0.2, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(symbol, "CALL", "LONG", longK, near, vol, spot, "TACTICAL", `長腿 Δ40 · ${near}`),
        optLeg(symbol, "CALL", "SHORT", shortK, near, vol, spot, "TACTICAL", `短腿 Δ20 · ${near}`),
      ],
    });
  }

  if (id === "PUT_DEBIT") {
    const longK = kNear(0.35, "PUT");
    const shortK = kNear(0.18, "PUT");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(symbol, "PUT", "LONG", longK, near, vol, spot, "CONVEXITY", `長腿 Δ35 · ${near}`),
        optLeg(symbol, "PUT", "SHORT", shortK, near, vol, spot, "CONVEXITY", `短腿 Δ18 · ${near}`),
      ],
    });
  }

  if (id === "BULL_PUT") {
    const shortK = kNear(0.2, "PUT");
    const longK = kNear(0.1, "PUT");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(symbol, "PUT", "SHORT", shortK, near, vol, spot, "CARRY", `短腿收 Theta · ${near}`),
        optLeg(symbol, "PUT", "LONG", longK, near, vol, spot, "CARRY", `外翼鎖尾部 · ${near}`),
      ],
    });
  }

  if (id === "BEAR_CALL") {
    const shortK = kNear(0.2, "CALL");
    const longK = kNear(0.1, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(symbol, "CALL", "SHORT", shortK, near, vol, spot, "CARRY", `短腿 · ${near}`),
        optLeg(symbol, "CALL", "LONG", longK, near, vol, spot, "CARRY", `外翼 · ${near}`),
      ],
    });
  }

  if (id === "COVERED_CALL") {
    const shortK = kNear(0.25, "CALL");
    const shares = overlayShares(spot);
    const contracts = Math.max(1, Math.round(shares / 100) || 1);
    const stockQty = contracts * 100;
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        stockLeg(symbol, spot, stockQty, "CORE"),
        optLeg(symbol, "CALL", "SHORT", shortK, near, vol, spot, "CARRY", `備兌短 Call · ${near}`, contracts),
      ],
    });
  }

  if (id === "CALENDAR_CALL") {
    const strike = kNear(0.45, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      farDte,
      legs: [
        optLeg(symbol, "CALL", "SHORT", strike, near, vol, spot, "CARRY", `近月短 Call ${near}`),
        optLeg(symbol, "CALL", "LONG", strike, far, vol, spot, "CONVEXITY", `遠月長 Call ${far}`),
      ],
    });
  }

  if (id === "CALENDAR_PUT") {
    const strike = kNear(0.35, "PUT");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      farDte,
      legs: [
        optLeg(symbol, "PUT", "SHORT", strike, near, vol, spot, "CARRY", `近月短 Put ${near}`),
        optLeg(symbol, "PUT", "LONG", strike, far, vol, spot, "CONVEXITY", `遠月長 Put ${far}`),
      ],
    });
  }

  if (id === "DIAGONAL_CALL") {
    const longK = kFar(0.4, "CALL");
    const shortK = kNear(0.25, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      farDte,
      legs: [
        optLeg(symbol, "CALL", "LONG", longK, far, vol, spot, "TACTICAL", `遠月長腿 ${far}`),
        optLeg(symbol, "CALL", "SHORT", shortK, near, vol, spot, "CARRY", `近月短腿 ${near}`),
      ],
    });
  }

  if (id === "IRON_CONDOR") {
    const shortPut = kNear(0.18, "PUT");
    const longPut = kNear(0.08, "PUT");
    const shortCall = kNear(0.18, "CALL");
    const longCall = kNear(0.08, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte,
      legs: [
        optLeg(symbol, "PUT", "LONG", longPut, near, vol, spot, "CARRY", `Put 外翼 ${near}`),
        optLeg(symbol, "PUT", "SHORT", shortPut, near, vol, spot, "CARRY", `Put 短腿 ${near}`),
        optLeg(symbol, "CALL", "SHORT", shortCall, near, vol, spot, "CARRY", `Call 短腿 ${near}`),
        optLeg(symbol, "CALL", "LONG", longCall, near, vol, spot, "CARRY", `Call 外翼 ${near}`),
      ],
    });
  }

  if (id === "LEAPS_CALL") {
    const strike = kFar(0.4, "CALL");
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte: farDte,
      farDte,
      legs: [optLeg(symbol, "CALL", "LONG", strike, far, vol, spot, "TACTICAL", `LEAPS Δ40 · ${far}`)],
    });
  }

  if (id === "PROTECTIVE") {
    const strike = kFar(0.25, "PUT");
    const shares = overlayShares(spot);
    const contracts = Math.max(1, Math.round(shares / 100) || 1);
    const stockQty = contracts * 100;
    return finish({
      id,
      ...meta,
      score: 0,
      why: [],
      avoid: false,
      symbol,
      spot,
      dte: farDte,
      farDte,
      legs: [
        stockLeg(symbol, spot, stockQty, "CORE"),
        optLeg(symbol, "PUT", "LONG", strike, far, vol, spot, "CONVEXITY", `保護 Put · ${far}`, contracts),
      ],
    });
  }

  const callK = kNear(0.22, "CALL");
  const putK = kNear(0.22, "PUT");
  const shares = overlayShares(spot);
  const contracts = Math.max(1, Math.round(shares / 100) || 1);
  const stockQty = contracts * 100;
  return finish({
    id: "COLLAR",
    ...STRATEGY_META.COLLAR,
    score: 0,
    why: [],
    avoid: false,
    symbol,
    spot,
    dte,
    legs: [
      stockLeg(symbol, spot, stockQty, "CORE"),
      optLeg(symbol, "CALL", "SHORT", callK, near, vol, spot, "CARRY", `領口短 Call · ${near}`, contracts),
      optLeg(symbol, "PUT", "LONG", putK, near, vol, spot, "CONVEXITY", `領口長 Put · ${near}`, contracts),
    ],
  });
}

type RankRow = { id: StrategyId; score: number; why: string[]; avoid: boolean };

export function preferredDte(id: StrategyId, regime: Regime): BuildOpts {
  if (id === "LEAPS_CALL") return { dte: 21, farDte: 180 };
  if (id === "LONG_PUT") {
    if (regime.id === "PANIC" || regime.id === "DISLOCATION") return { dte: 45 };
    return { dte: 90 };
  }
  if (id === "CALENDAR_CALL" || id === "CALENDAR_PUT" || id === "DIAGONAL_CALL")
    return { dte: 21, farDte: 90 };
  if (id === "PROTECTIVE") return { dte: 21, farDte: 90 };
  if (id === "IRON_CONDOR" || id === "BULL_PUT" || id === "BEAR_CALL" || id === "COVERED_CALL")
    return { dte: 21 };
  if (id === "CALL_DEBIT" || id === "PUT_DEBIT" || id === "LONG_CALL") return { dte: 21 };
  return { dte: 21 };
}

export function rankStrategies(quote: QuoteBar, regime: Regime, ivRank: number): RankRow[] {
  const levered = quote.symbol === "TQQQ" || quote.symbol === "SQQQ" || quote.symbol === "UPRO";
  const strong = quote.trend >= 36 && quote.signal !== "SELL";
  const weak = quote.signal === "SELL" || quote.trend <= -20;
  const cheapIv = ivRank < 40;
  const richIv = ivRank >= 55;
  const rows: RankRow[] = [];

  const add = (id: StrategyId, score: number, why: string[], avoid = false) => {
    rows.push({ id, score: Math.max(0, Math.min(100, score)), why, avoid });
  };

  if (levered) {
    add("LONG_STOCK", regime.id === "NORMAL" || regime.id === "RECOVERY" ? 78 : 32, [
      "槓桿 ETF 只作戰術 Beta",
      "禁止再疊 Short Gamma",
    ], regime.id === "PANIC" || regime.id === "DISLOCATION");
    add("CALL_DEBIT", 28, ["3× 再叠加期權會把尾部疊在同一邊"], true);
    add("BULL_PUT", 12, ["TQQQ + 短 Put = 槓桿短 Gamma"], true);
    add("IRON_CONDOR", 8, ["槓桿標的禁止賣鐵鷹"], true);
    add("CALENDAR_CALL", 16, ["3× 的日曆價差 Gamma 不對稱"], true);
    add("LONG_PUT", regime.id === "EARLY_STRESS" || regime.id === "DISLOCATION" ? 70 : 40, [
      "若一定要期權，只考慮有限風險長 Put",
    ]);
    return rows.sort((a, b) => b.score - a.score);
  }

  switch (regime.id) {
    case "NORMAL":
      add("CALL_DEBIT", cheapIv && strong ? 91 : strong ? 78 : 62, [
        cheapIv ? "IV 不貴，借記價差買凸性" : "IV 中性，用價差限制權利金",
        strong ? "趨勢與體制同向" : "趨勢一般，倉要小",
      ]);
      add("LONG_STOCK", strong ? 87 : 70, ["核心參與長期增長", quote.signalNote]);
      add("BULL_PUT", richIv && strong ? 86 : richIv ? 74 : 58, [
        richIv ? "IV 偏貴，改收有限風險 Theta" : "IV 不貴時貸記價差性價比一般",
        "外翼必須在，禁止裸賣",
      ], weak);
      add("IRON_CONDOR", richIv ? 80 : 44, [
        richIv ? "貴 IV 用鐵鷹收雙邊時間，兩翼都要鎖" : "便宜 IV 不急著賣鐵鷹",
      ], weak);
      add("CALENDAR_CALL", richIv ? 76 : 58, ["近月賣時間、遠月留 Vega：這就是緩衝市場的時間差"]);
      add("DIAGONAL_CALL", strong ? 70 : 52, ["對角 = 日曆 + 方向，適合溫和偏多"]);
      add("COVERED_CALL", richIv ? 76 : 54, [richIv ? "貴 IV 賣備兌" : "便宜 IV 不急著賣 Call"]);
      add("LEAPS_CALL", cheapIv && strong ? 68 : 42, [cheapIv ? "遠月 Call 替代一部分正股 Beta" : "IV 貴時 LEAPS 太貴"]);
      add("LONG_CALL", cheapIv && strong ? 73 : 48, [cheapIv ? "權利金便宜才考慮裸 Call" : "IV 貴時 naked long call 衰減快"]);
      add("LONG_PUT", 48, ["90DTE 深虛值 Put 是調整權，不是看空"]);
      add("CALENDAR_PUT", 50, ["用 Put 日曆同時收時間與留尾部"]);
      add("COLLAR", 50, ["正常體制不必鎖死上行"]);
      add("PROTECTIVE", 40, ["保險可以留一點，但不是主攻"]);
      add("PUT_DEBIT", 44, ["不是主策略，除非要便宜保險"]);
      add("BEAR_CALL", 28, ["與偏多體制相反"], true);
      break;
    case "EARLY_STRESS":
      add("PUT_DEBIT", 90, ["壓力早期用有限風險買凸性", "比裸 Put 便宜"]);
      add("COLLAR", 82, ["正股留下、鎖尾部、賣掉部分上行"]);
      add("PROTECTIVE", 80, ["先把尾部鎖上，再決定 Beta"]);
      add("LONG_PUT", 76, ["淨 Vega 轉正"]);
      add("CALENDAR_PUT", 72, ["近月短 Put 若還有 Carry，遠月必須更長"]);
      add("LONG_STOCK", 48, ["降低 Beta，不是清倉"]);
      add("CALL_DEBIT", 42, ["只留強勢標的的小倉"]);
      add("DIAGONAL_CALL", 38, ["壓力期對角的短腿會痛"]);
      add("BULL_PUT", 34, ["短 Gamma 在壓力期不划算"], true);
      add("IRON_CONDOR", 22, ["雙邊短倉在波動抬升時兩邊都虧"], true);
      add("COVERED_CALL", 40, ["可收一點，但不要加碼短倉"]);
      add("CALENDAR_CALL", 36, ["Call 日曆在下跌時遠月也會被打"]);
      add("BEAR_CALL", 55, ["若要收 Theta，用有限風險上檔"]);
      add("LEAPS_CALL", 24, ["不要在 IV 抬升時追遠月 Call"], true);
      add("LONG_CALL", 22, ["不要在 IV 抬升時追 Call"], true);
      break;
    case "DISLOCATION":
    case "PANIC":
      add("LONG_PUT", 92, ["凸性是購買力，不是預測最低點"]);
      add("PUT_DEBIT", 80, ["若權利金太貴，用價差控制成本"]);
      add("PROTECTIVE", 74, ["留下核心、鎖住崩盤"]);
      add("COLLAR", 70, ["留下核心、鎖住崩盤"]);
      add("CALENDAR_PUT", 58, ["只在遠月明顯更貴的凸性時才留日曆"]);
      add("LONG_STOCK", 22, ["此時加 Beta 是在賭反彈"], true);
