export function plansForQuote(
  quote: QuoteBar,
  regime: Regime,
  iv: number,
  ivRank: number,
  limit = 6,
): StrategyPlan[] {
  const ranked = rankStrategies(quote, regime, ivRank);
  const picked = ranked.filter((r) => !r.avoid).slice(0, limit);
  const avoidTop = ranked.find((r) => r.avoid);
  const out = picked.map((r) => {
    const plan = buildStrategy(r.id, quote, iv, preferredDte(r.id, regime));
    plan.score = r.score;
    plan.why = r.why;
    plan.avoid = r.avoid;
    return plan;
  });
  if (avoidTop && !out.some((p) => p.id === avoidTop.id)) {
    const bad = buildStrategy(avoidTop.id, quote, iv, preferredDte(avoidTop.id, regime));
    bad.score = avoidTop.score;
    bad.why = avoidTop.why;
    bad.avoid = true;
    out.push(bad);
  }
  return out;
}

export function catalogPlan(id: StrategyId, quote: QuoteBar, iv: number, dte: number): StrategyPlan {
  const far = dte >= 90 ? Math.max(dte, 180) : Math.max(dte + 70, 90);
  return buildStrategy(id, quote, iv, { dte, farDte: far });
}

/** Minimal quote so a typed-in ticker (MSFT / APPL) can still forge a ticket. */
export function stubQuote(symbol: string, price: number, iv?: number): QuoteBar {
  const px = price;
  const vol = iv && iv > 0 ? iv : ivFallback(symbol);
  return {
    symbol,
    price: px,
    changePct: 0,
    prevClose: px,
    volume: 0,
    avgVol20: 0,
    high52: px,
    low52: px,
    ma20: px,
    ma50: px,
    ma200: px,
    rv20: vol,
    rv60: vol,
    rv252: vol,
    ivRankProxy: 50,
    volumeZ: 0,
    trend: 0,
    signal: "HOLD",
    signalNote: "試算定價",
    asOf: Date.now(),
  };
}
